#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "live_session_scene_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);RetainedShotTimelineCandidate timeline(graph,2237);size_t frames=0;for(uint32_t shot:{20053u,32107u}){auto refs=hierarchyRefs(graph,graph.elements.at(shot),"timeFrame",1);if(refs.size()!=1)throw std::runtime_error("shot frame");AnimationTimeFrame time(graph,graph.elements.at(refs[0]));auto start=time.start;if(selectFilmShotCandidate(graph,2237,start).clip!=shot)throw std::runtime_error("shot time mapping requires inverse hierarchy");for(int32_t offset:{0,167,333}){auto sample=evaluateLiveSessionSceneCandidate(timeline,start+offset,512,512);if(sample.scene.shot!=shot||sample.scene.models.size()!=(shot==20053?4:3))throw std::runtime_error("live scene lost models");std::cout<<"shot="<<shot<<" tick="<<start+offset<<" models="<<sample.scene.models.size()<<" executed="<<sample.evaluation.executed<<" rebuilt="<<sample.evaluation.rebuilt<<"\n";++frames;}}std::cout<<"evaluated multi-model scenes passed frames="<<frames<<" gpu_multi_model=unfinished native_parity=unverified\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
